export const CATALOG: CatalogItem[] = RAW.map((it, i) => ({ id: "I" + (i + 1), ...it }));

export const CATALOG_BY_ID: Map<string, CatalogItem> = new Map(
  CATALOG.map((it) => [it.id, it])
);

// Distinct suppliers in catalog order, each with their PO and ordered category list.
export const SUPPLIERS: { supplier: string; po: string }[] = (() => {
  const seen = new Map<string, string>();
  for (const it of CATALOG) if (!seen.has(it.supplier)) seen.set(it.supplier, it.po);
  return Array.from(seen, ([supplier, po]) => ({ supplier, po }));
})();
